# 配种大叔基础类定义
class 配种大叔:
    def __init__(self):
        self.level = 1  # 当前等级
        self.max_level = 50  # 等级上限
        self.skills = {}  # 已习得技能
        self.debuffs = {}  # 可施加的负面状态

    # 升级条件检查与处理
    def check_level_up(self, trigger_type, value=None):
        if self.level >= self.max_level:
            return False

        level_up = False

        # 射精触发升级
        if trigger_type == "ejaculation":
            self.level += 1
            level_up = True

        # 女性高潮触发升级
        elif trigger_type == "female orgasm":
            self.level += 1
            level_up = True

        # 好感度达标触发升级
        elif trigger_type == "好感度" and value >= 100:
            if not self.level_up_records["好感度"]:
                self.level += 5
                self.level_up_records["好感度"] = True
                level_up = True

        # 忠诚度达标触发升级
        elif trigger_type == "忠诚度" and value >= 100:
            if not self.level_up_records["忠诚度"]:
                self.level += 5
                self.level_up_records["忠诚度"] = True
                level_up = True

        # 目标屈服状态触发升级
        elif trigger_type == "屈服":
            self.level += 5
            level_up = True

        # 检查等级上限
        if self.level > self.max_level:
            self.level = self.max_level

        return level_up

    # 技能系统
    def learn_skills(self):
        # 2级获得核心技能'弱化'
        if self.level >= 2:
            self.skills["weaken"] = {
                "name": "弱化",
                "level": 1,
                "description": "对女性施加快感时有几率施加负面状态"
            }

    # 弱化技能触发判定
    def try_weaken(self, target, action_type):
        if "weaken" not in self.skills:
            return None

        # 根据行为类型选择合适的负面状态
        possible_debuffs = self.get_suitable_debuffs(action_type)

        # 概率触发
        if random.random() < 0.3:  # 30%触发率
            chosen_debuff = random.choice(possible_debuffs)
            return self.apply_debuff(target, chosen_debuff)
        return None

    # 根据行为选择合适的负面状态
    def get_suitable_debuffs(self, action_type):
        # 从<负面状态>表中筛选符合条件的状态
        # 需要结合角色等级限制
        pass

    # 施加负面状态
    def apply_debuff(self, target, debuff_type):
        if self.level >= debuff_type.required_level:
            target.add_debuff(debuff_type)
            return True
        return False

